BEGIN;
CREATE TABLE IF NOT EXISTS provider.profession (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(50) UNIQUE NOT NULL, label_fr text NOT NULL, label_nl text);
CREATE TABLE IF NOT EXISTS provider.speciality (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(50) UNIQUE NOT NULL, name_fr text NOT NULL, name_nl text, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS provider.healthcare_provider (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid REFERENCES core.organization(id), inami_number varchar(30), first_name text, last_name text, display_name text NOT NULL, profession_id uuid REFERENCES provider.profession(id), source varchar(80), valid_from date, valid_to date, last_verified_at timestamptz, active boolean NOT NULL DEFAULT true);
CREATE UNIQUE INDEX IF NOT EXISTS uq_provider_inami ON provider.healthcare_provider(inami_number) WHERE inami_number IS NOT NULL;
CREATE TABLE IF NOT EXISTS provider.provider_speciality (provider_id uuid REFERENCES provider.healthcare_provider(id) ON DELETE CASCADE, speciality_id uuid REFERENCES provider.speciality(id), is_primary boolean NOT NULL DEFAULT false, valid_from date, valid_to date, PRIMARY KEY(provider_id,speciality_id,valid_from));

CREATE TABLE IF NOT EXISTS agenda.resource (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), facility_id uuid NOT NULL REFERENCES core.facility(id), resource_type varchar(40) NOT NULL, code varchar(50) NOT NULL, name text NOT NULL, UNIQUE(facility_id,code));
CREATE TABLE IF NOT EXISTS agenda.booking_group (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), facility_id uuid NOT NULL REFERENCES core.facility(id), household_id uuid REFERENCES patient.household(id), booked_by_patient_id uuid REFERENCES patient.patient(id), contact_point_id uuid REFERENCES patient.contact_point(id), notification_policy varchar(30) NOT NULL DEFAULT 'INDIVIDUAL', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agenda.appointment (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), facility_id uuid NOT NULL REFERENCES core.facility(id), patient_id uuid REFERENCES patient.patient(id), provider_id uuid REFERENCES provider.healthcare_provider(id), resource_id uuid REFERENCES agenda.resource(id), booking_group_id uuid REFERENCES agenda.booking_group(id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, status varchar(30) NOT NULL DEFAULT 'scheduled', reason text, source varchar(50) DEFAULT 'local', CHECK(ends_at>starts_at));

CREATE TABLE IF NOT EXISTS encounter.encounter (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), facility_id uuid NOT NULL REFERENCES core.facility(id), patient_id uuid NOT NULL REFERENCES patient.patient(id), appointment_id uuid REFERENCES agenda.appointment(id), responsible_provider_id uuid REFERENCES provider.healthcare_provider(id), speciality_id uuid REFERENCES provider.speciality(id), status varchar(30) NOT NULL DEFAULT 'planned', started_at timestamptz, ended_at timestamptz);
CREATE TABLE IF NOT EXISTS encounter.worksheet_definition (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), speciality_id uuid REFERENCES provider.speciality(id), code varchar(80) NOT NULL, name text NOT NULL, version integer NOT NULL DEFAULT 1, schema_json jsonb NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(speciality_id,code,version));
CREATE TABLE IF NOT EXISTS encounter.worksheet_instance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), encounter_id uuid NOT NULL REFERENCES encounter.encounter(id) ON DELETE CASCADE, definition_id uuid NOT NULL REFERENCES encounter.worksheet_definition(id), data_json jsonb NOT NULL DEFAULT '{}', status varchar(30) NOT NULL DEFAULT 'draft', authored_by uuid REFERENCES core.app_user(id), validated_by uuid REFERENCES core.app_user(id), validated_at timestamptz);

CREATE TABLE IF NOT EXISTS inami.nomenclature_release (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source varchar(80) NOT NULL, source_version varchar(100) NOT NULL, published_at date, imported_at timestamptz NOT NULL DEFAULT now(), checksum text, UNIQUE(source,source_version));
CREATE TABLE IF NOT EXISTS inami.nomenclature_code (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(20) NOT NULL, title_fr text NOT NULL, title_nl text, description_fr text, description_nl text, valid_from date NOT NULL, valid_to date, release_id uuid REFERENCES inami.nomenclature_release(id), source_reference text, UNIQUE(code,valid_from));
CREATE TABLE IF NOT EXISTS inami.tariff (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nomenclature_code_id uuid NOT NULL REFERENCES inami.nomenclature_code(id), patient_category varchar(80) NOT NULL DEFAULT 'standard', convention_status varchar(50), amount numeric(12,2), reimbursement_amount numeric(12,2), patient_amount numeric(12,2), currency char(3) NOT NULL DEFAULT 'EUR', valid_from date NOT NULL, valid_to date, release_id uuid REFERENCES inami.nomenclature_release(id));
CREATE TABLE IF NOT EXISTS inami.nomenclature_rule (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nomenclature_code_id uuid REFERENCES inami.nomenclature_code(id), rule_type varchar(80) NOT NULL, description_fr text NOT NULL, machine_rule jsonb, valid_from date, valid_to date, source_reference text);

CREATE TABLE IF NOT EXISTS insurability.mutuality (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(30) UNIQUE NOT NULL, name_fr text NOT NULL, name_nl text, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS integration.provider (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(80) UNIQUE NOT NULL, name text NOT NULL, base_url text, environment varchar(30) NOT NULL DEFAULT 'test', credential_secret_ref text, active boolean NOT NULL DEFAULT false, config jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS integration.external_exchange (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_id uuid NOT NULL REFERENCES integration.provider(id), service varchar(80) NOT NULL, direction varchar(10) NOT NULL, correlation_id text, requested_at timestamptz, responded_at timestamptz, http_status integer, payload_encrypted bytea, payload_hash text, processing_status varchar(30), error_code text, retention_until date);
CREATE TABLE IF NOT EXISTS integration.sync_job (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_id uuid NOT NULL REFERENCES integration.provider(id), resource varchar(80) NOT NULL, status varchar(30) NOT NULL DEFAULT 'queued', cursor jsonb, started_at timestamptz, completed_at timestamptz, records_read integer NOT NULL DEFAULT 0, records_created integer NOT NULL DEFAULT 0, records_updated integer NOT NULL DEFAULT 0, records_rejected integer NOT NULL DEFAULT 0, source_version text, error_message text);
CREATE TABLE IF NOT EXISTS insurability.insurability_check (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patient.patient(id), facility_id uuid NOT NULL REFERENCES core.facility(id), requested_by uuid REFERENCES core.app_user(id), requested_at timestamptz NOT NULL DEFAULT now(), service varchar(80) NOT NULL, status varchar(40) NOT NULL, coverage_from date, coverage_to date, mutuality_id uuid REFERENCES insurability.mutuality(id), beneficiary_category varchar(80), request_reference text, response_reference text, external_response_id uuid REFERENCES integration.external_exchange(id), summary jsonb NOT NULL DEFAULT '{}');

CREATE TABLE IF NOT EXISTS billing.service (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), encounter_id uuid REFERENCES encounter.encounter(id), patient_id uuid NOT NULL REFERENCES patient.patient(id), provider_id uuid NOT NULL REFERENCES provider.healthcare_provider(id), nomenclature_code_id uuid REFERENCES inami.nomenclature_code(id), tariff_id uuid REFERENCES inami.tariff(id), service_date date NOT NULL, quantity numeric(10,2) NOT NULL DEFAULT 1, unit_amount numeric(12,2), total_amount numeric(12,2), reimbursement_amount numeric(12,2), patient_amount numeric(12,2), status varchar(30) NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS billing.claim (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), facility_id uuid NOT NULL REFERENCES core.facility(id), patient_id uuid NOT NULL REFERENCES patient.patient(id), provider_id uuid NOT NULL REFERENCES provider.healthcare_provider(id), encounter_id uuid REFERENCES encounter.encounter(id), claim_type varchar(30) NOT NULL, status varchar(30) NOT NULL DEFAULT 'draft', external_reference text, submitted_at timestamptz, rejection_code text, rejection_message text, idempotency_key uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE);
CREATE TABLE IF NOT EXISTS billing.claim_line (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), claim_id uuid NOT NULL REFERENCES billing.claim(id) ON DELETE CASCADE, service_id uuid NOT NULL REFERENCES billing.service(id), sequence_no integer NOT NULL, nomenclature_code_snapshot varchar(20) NOT NULL, service_date date NOT NULL, amount numeric(12,2), status varchar(30) NOT NULL DEFAULT 'pending', UNIQUE(claim_id,sequence_no));

CREATE TABLE IF NOT EXISTS inventory.item (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES core.organization(id), sku varchar(80) NOT NULL, name text NOT NULL, unit varchar(30) NOT NULL, UNIQUE(organization_id,sku));
CREATE TABLE IF NOT EXISTS inventory.location (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), facility_id uuid NOT NULL REFERENCES core.facility(id), code varchar(50) NOT NULL, name text NOT NULL, UNIQUE(facility_id,code));
CREATE TABLE IF NOT EXISTS inventory.stock_movement (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_id uuid NOT NULL REFERENCES inventory.item(id), location_id uuid NOT NULL REFERENCES inventory.location(id), encounter_id uuid REFERENCES encounter.encounter(id), movement_type varchar(30) NOT NULL, quantity numeric(14,3) NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), created_by uuid REFERENCES core.app_user(id));

CREATE TABLE IF NOT EXISTS correspondence.template (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES core.organization(id), code varchar(80) NOT NULL, name text NOT NULL, language varchar(10) NOT NULL, subject_template text, body_template text NOT NULL, variable_schema jsonb NOT NULL DEFAULT '{}', version integer NOT NULL DEFAULT 1, active boolean NOT NULL DEFAULT true, UNIQUE(organization_id,code,language,version));
CREATE TABLE IF NOT EXISTS correspondence.document (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid REFERENCES patient.patient(id), encounter_id uuid REFERENCES encounter.encounter(id), template_id uuid REFERENCES correspondence.template(id), rendered_subject text, rendered_body text, variables_used jsonb NOT NULL DEFAULT '{}', status varchar(30) NOT NULL DEFAULT 'draft', validated_by uuid REFERENCES core.app_user(id), validated_at timestamptz, storage_key text);
CREATE TABLE IF NOT EXISTS notification.message (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid REFERENCES patient.patient(id), appointment_id uuid REFERENCES agenda.appointment(id), booking_group_id uuid REFERENCES agenda.booking_group(id), channel varchar(20) NOT NULL, destination_contact_id uuid REFERENCES patient.contact_point(id), status varchar(30) NOT NULL DEFAULT 'queued', scheduled_at timestamptz, sent_at timestamptz, provider_message_id text, error_code text);

CREATE TABLE IF NOT EXISTS audit.event (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid REFERENCES core.organization(id), facility_id uuid REFERENCES core.facility(id), actor_user_id uuid REFERENCES core.app_user(id), patient_id uuid REFERENCES patient.patient(id), action varchar(100) NOT NULL, entity_type varchar(100), entity_id uuid, occurred_at timestamptz NOT NULL DEFAULT now(), ip_address inet, request_id text, success boolean NOT NULL DEFAULT true, metadata jsonb NOT NULL DEFAULT '{}');
COMMIT;
